// Normalized data model — mirrors web/public/data/plasticity.json
// (generated by web/scripts/build_data.py from results/tables/*.json).

export type MatchStep = "applicable" | "reference" | "na";

export interface MethodMeta {
  key: string;
  short: string;
  name: string;
  tag: string;
  family: "control" | "magnitude" | "directional" | "other";
  normControl: string;
  matchStep: MatchStep;
}

export interface Arm extends MethodMeta {
  acc: number;
  accStd: number;
  decay: number;
  decayStd: number;
  norm: number;
  normStd: number;
  dormant: number;
  dormantStd: number;
  effRank: number | null;
  effRankStd: number | null;
  matchDev: number | null;
  peakAcc?: number | null;
  endAcc?: number | null;
}

export interface PerSeedRow {
  seed: number;
  acc: number;
  decay: number;
  norm: number;
  dormant: number;
  effRank?: number;
  peakAcc?: number;
  endAcc?: number;
  matchDev?: number;
}

export interface R20Config {
  dataset: string;
  architecture: string;
  tasks: number;
  stepsPerTask: number;
  lr: number;
  trainSubset: number;
  batch: number;
  epochs: number;
  classifier: string;
  seeds: number;
  hidden: number;
  depth: number;
}

export interface R20 {
  id: string;
  name: string;
  status: string;
  subtitle: string;
  dataset: string;
  architecture: string;
  arch: string;
  config: R20Config;
  seeds: number[];
  arms: Arm[];
  perSeed: Record<string, PerSeedRow[]>;
  verdict?: string;
  source: string;
}

export interface LambdaPoint {
  lam: number;
  acc: number;
  accStd: number;
  decay: number;
  decayStd: number;
  norm: number;
  normStd: number;
  dormant: number;
  dormantStd: number;
}

export interface RadialPoint {
  gamma: number;
  acc: number;
  accStd: number;
  decay: number;
  decayStd: number;
  norm: number;
  normStd: number;
  dormant: number;
  dormantStd: number;
  effRank: number | null;
  radialAlign: number | null;
  matchDev: number | null;
}

export interface AblationVariant {
  key: string;
  name: string;
  tag: string;
  reference: boolean;
  acc: number;
  accStd: number;
  decay: number;
  decayStd: number;
  norm: number;
  normStd: number;
  dormant: number;
  dormantStd: number;
}

export interface RegimePoint extends MethodMeta {
  norm: number | null;
  decay: number | null;
  acc: number | null;
  dormant: number | null;
}

export interface Regime {
  id: string;
  name: string;
  short: string;
  dataset: string;
  arch: string;
  seeds: number;
  arms: number;
  pearson: number | null;
  computedHere?: boolean;
  source: string;
  points: RegimePoint[];
}

export interface AnglePoint {
  cos: number;
  acc: number;
  accStd: number;
  norm: number;
  normStd: number;
  gradAlign: number | null;
}

export interface NormPlasticityPoint extends MethodMeta {
  norm: number;
  decay: number;
  acc: number;
}

export interface RawFile {
  name: string;
  path: string;
  bytes: number;
}

export interface PlasticityData {
  generatedAt: string;
  meta: {
    arms: number;
    seedsPerArm: number;
    tasks: number;
    architectures: number;
    datasets: number;
    architectureList: string[];
    datasetList: string[];
    hardware: Record<string, unknown>;
    matchedStepTolerance: string;
  };
  r20: R20;
  lambda_: {
    values: number[];
    points: LambdaPoint[];
    seeds: number;
    grid?: string;
    source: string;
    observation: string;
  };
  radial: {
    gammas: number[];
    points: RadialPoint[];
    perSeed: Record<string, PerSeedRow[]>;
    seeds: number;
    note?: string;
    source: string;
    observation: string;
  };
  ablation: {
    variants: AblationVariant[];
    seeds: number;
    source: string;
    observation: string;
  };
  regimes: Regime[];
  angle: {
    cos: number[];
    points: AnglePoint[];
    arch: string;
    source: string;
  };
  normPlasticity: {
    primary: {
      pearson: number;
      spearman: number;
      n: number;
      accPearson: number;
      points: NormPlasticityPoint[];
    };
    effRankAcc: number;
    effRankDecay: number;
    source: string;
  };
  rawFiles: RawFile[];
}
